async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let reachedEOF = false;
  let state = initial;
  let physicalLine = 1;
  let recordIndex = 0;
  let fragments = [];

  async function processLine(line) {
    const lineNumber = physicalLine++;
    if (line.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch (error) {
      if (error instanceof SyntaxError) return false;
      throw error;
    }

    const result = await reduce(state, value, {
      physicalLine: lineNumber,
      recordIndex: recordIndex++
    });
    state = result.state;
    return result.done === true;
  }

  try {
    while (true) {
      const item = await iterator.next();
      let text;

      if (item.done) {
        reachedEOF = true;
        text = decoder.decode();
      } else {
        text = decoder.decode(item.value, { stream: true });
      }

      let start = 0;
      let end;
      while ((end = text.indexOf("\n", start)) !== -1) {
        fragments.push(text.slice(start, end));
        const line = fragments.join("");
        fragments = [];
        if (await processLine(line)) return state;
        start = end + 1;
      }

      if (start < text.length) {
        fragments.push(text.slice(start));
      }

      if (reachedEOF) {
        if (fragments.length > 0) {
          const line = fragments.join("");
          fragments = [];
          await processLine(line);
        }
        return state;
      }
    }
  } finally {
    if (!reachedEOF) {
      const close = iterator.return;
      if (typeof close === "function") {
        await close.call(iterator);
      }
    }
  }
}
